  try { var v = ctx.variables.getVar("phosphobot_url"); if (v) return String(v).replace(/\/$/, ""); } catch (e) {}
  if (window.phosphobot_url) return String(window.phosphobot_url).replace(/\/$/, "");
  try { var ls = localStorage.getItem("phosphobot_url"); if (ls) return String(ls).replace(/\/$/, ""); } catch (e) {}
  return "http://127.0.0.1:8021";
}
function post(ctx, path, body) {
  var xhr = new XMLHttpRequest();
  xhr.open("POST", base(ctx) + path, false);
  xhr.setRequestHeader("Content-Type", "application/json");
  xhr.send(JSON.stringify(body || {}));
  if (xhr.status < 200 || xhr.status >= 300) { throw new Error(path + " HTTP " + xhr.status + ": " + xhr.responseText); }
  return JSON.parse(xhr.responseText || "{}");
}
function getNum(ctx, name, fallback) {
  try { var v = ctx.variables.getVar(name); return Number(v == null || v === "" ? fallback : v); }
  catch (e) { return Number(window[name] == null ? fallback : window[name]); }
}
function deg2mu(d) { return d * 4096 / 360 + 2048; }
var rid = Math.max(1, parseInt(robot, 10) || 1) - 1;
var idx = Math.max(1, parseInt(joint, 10) || 1) - 1;
var readMu = post(this, "/joints/read?robot_id=" + rid, {source: "robot", unit: "motor_units"});
var angles = (readMu.angles || []).map(function (a) { return Math.round(Number(a)); });
var current = !isFinite(angles[idx]) ? 0 : (angles[idx] - 2048) * 360 / 4096;
var step = Math.max(0.001, Number(dt) || 0.1);
var error = Number(target) - current;
var p = getNum(this, "pid_p", 1);
var i = getNum(this, "pid_i", 0);
var d = getNum(this, "pid_d", 0);
window.pid_integral = Number(window.pid_integral || 0) + error * step;
var derivative = (error - Number(window.pid_last_error || 0)) / step;
window.pid_last_error = error;
var output = p * error + i * window.pid_integral + d * derivative;
var next = current + output;
angles[idx] = Math.round(deg2mu(next));
if (angles.length < 6 || angles.some(function (n) { return !isFinite(n); })) { throw new Error("関節角度を読めませんでした(null)。キャリブレーションが済んでいるか、ロボット番号が合っているか確認してください。"); }
var result = post(this, "/joints/write?robot_id=" + rid, {angles: angles, unit: "motor_units"});
try {
  this.variables.setVar("current_angle", current);
  this.variables.setVar("target_angle", Number(target));
  this.variables.setVar("pid_error", error);
  this.variables.setVar("pid_integral", window.pid_integral);
  this.variables.setVar("pid_derivative", derivative);
  this.variables.setVar("last_response", JSON.stringify(result));
} catch (e) {}
return "";

